WITH flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) > INTERVAL 45 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT id, device_code, reading_ts, humidity, pressure, firmware, session_id, CASE WHEN device_code RLIKE '^(DV-03|DV-04)$' THEN 'PRIORITY' WHEN device_code RLIKE '^(DV-01|DV-02)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS device_code_zone FROM islands ORDER BY pressure DESC NULLS FIRST
